attributes.placeholder:
{
                  selected === 'rejected' ? 'Reason for rejection...' :
                  selected === 'changes_requested' ? 'What changes are needed...' :
                  'Optional notes...'
                }

attributes.className:
{cn(
              'h-12 w-10 rounded-md border text-center text-lg font-bold text-slate-900',
              'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent',
              'disabled:opacity-50 transition-colors',
              digit ? 'border-indigo-400 bg-indigo-50' : 'border-slate-300 bg-white',
            )}

{cn(
                      'block w-full rounded-md border px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400',
                      'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent transition-colors',
                      errors.email ? 'border-rose-500 bg-rose-50' : 'border-slate-300 bg-white',
                    )}

{cn(
                        'block w-full rounded-md border px-3 py-2 pr-10 text-sm text-slate-900',
                        'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent transition-colors',
                        errors.password ? 'border-rose-500 bg-rose-50' : 'border-slate-300 bg-white',
                      )}

{cn(
                      'block w-full rounded-md border px-3 py-2 text-sm text-slate-900',
                      'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent transition-colors',
                      errors.confirmPassword ? 'border-rose-500 bg-rose-50' : 'border-slate-300 bg-white',
                    )}

attributes.onChange:
{(e) => {
                  const [sortBy, sortDir] = e.target.value.split(':') as [typeof filters.sortBy, typeof filters.sortDir];
                  setFilters((f) => ({ ...f, sortBy, sortDir, page: 1 }));
                }}

{(e) => {
            const file = e.target.files?.[0];
            if (file) handleFile(file);
            e.target.value = ''; // reset so same file can be re-uploaded
          }}

attributes.className:
{cn(
                'block w-full rounded-md border px-3 py-2 text-sm',
                'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent',
                errors.email ? 'border-rose-500 bg-rose-50' : 'border-slate-300',
              )}

{cn(
                'block w-full rounded-md border px-3 py-2 text-sm',
                'focus:outline-none focus:ring-2 focus:ring-indigo-600 focus:border-transparent',
                errors.role ? 'border-rose-500 bg-rose-50' : 'border-slate-300',
              )}

{cn(
                      'flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm font-medium transition-colors',
                      isActive
                        ? 'bg-indigo-50 text-indigo-700'
                        : 'text-slate-600 hover:bg-slate-100 hover:text-slate-900',
                    )}
